-- Seed data for DD_ProductNesting (Cilíndricos + Cónicos families) and the Classification
-- fix for the TCD-* (Cilíndrico doble capa) products that are missing it.
--
-- Generated by Claude Code from CATALOGO_QTANQUE.md / ANIDADO_TANQUES_SAP.md in this repo.
-- NOT executed against any server. Run only after create_dd_productnesting.sql has been
-- properly applied through the Application Dictionary (see that file's header).
--
-- NestedVolume is left NULL everywhere on purpose — it has not been measured for any model.
-- Do not fill it with guessed numbers; see MDDProductNesting.allocateFootprintVolume() for how
-- the plugin behaves safely in the meantime (nested units count as 0 marginal volume, a
-- conservative placeholder, not an estimate).

BEGIN;

-- =====================================================================
-- BLOCK 1 — Populate M_Product.Classification for the 6 TCD-* products
-- (Cilíndrico doble capa 520/1060) that are currently empty. Without this
-- they cannot be matched into the CILINDRICO family below at all.
-- =====================================================================

SELECT value, classification FROM adempiere.m_product
WHERE value LIKE 'TCD-0520-%' OR value LIKE 'TCD-1060-%'
ORDER BY value;
-- expected before: classification = '' or NULL on all 6 rows

UPDATE adempiere.m_product
SET classification = 'TCD-0520', updated = now()
WHERE value LIKE 'TCD-0520-%';

UPDATE adempiere.m_product
SET classification = 'TCD-1060', updated = now()
WHERE value LIKE 'TCD-1060-%';

SELECT value, classification, volume FROM adempiere.m_product
WHERE value LIKE 'TCD-0520-%' OR value LIKE 'TCD-1060-%'
ORDER BY value;
-- expected after: classification populated, volume unchanged (already set by populate_volume_qtanque.sql)


-- =====================================================================
-- BLOCK 2 — DD_ProductNesting seed rows
-- =====================================================================
-- AD_Client_ID/AD_Org_ID/CreatedBy/UpdatedBy below use 0 / 100 following the same
-- convention as the rest of this repo's scripts (system client/org, admin user) —
-- adjust to match this instance's real client/org before running.

INSERT INTO adempiere.dd_productnesting
    (dd_productnesting_id, ad_client_id, ad_org_id, isactive, created, createdby, updated, updatedby,
     classification, nestingfamily, seqno, nestedvolume, description)
VALUES
    -- CILINDRICO family — order from CATALOGO_QTANQUE.md: 370 < 500 < 550 < 700 < 900 < 1060
    -- (TCD-* doble-capa sizes interleaved at the same rank as their liso equivalent; they are a
    --  distinct Classification but the same nominal size, so they share SeqNo with their liso peer)
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TLL-0370', 'CILINDRICO', 1, NULL, 'Cilíndrico 370'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TLL-0500', 'CILINDRICO', 2, NULL, 'Cilíndrico 500'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TLL-0550', 'CILINDRICO', 3, NULL, 'Cilíndrico 550'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCD-0520', 'CILINDRICO', 2, NULL, 'Cilíndrico 2kapas 520 (doble capa, mismo rango que el 500 liso)'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TLL-0700', 'CILINDRICO', 4, NULL, 'Cilíndrico 700'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TLL-0900', 'CILINDRICO', 5, NULL, 'Cilíndrico 900 / Q''Gigante 900'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TLL-1060', 'CILINDRICO', 6, NULL, 'Cilíndrico 1060 / Q''Gigante 1060'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCD-1060', 'CILINDRICO', 6, NULL, 'Cilíndrico 2kapas 1060 (doble capa, mismo rango que el 1060 liso)'),

    -- CONICO family — order: 600 < 900 < 1000 < 1200 < 1700 < 2500 < 5200
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCL-0600', 'CONICO', 1, NULL, 'Cónico 600'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCL-0900', 'CONICO', 2, NULL, 'Cónico 900'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCL-1000', 'CONICO', 3, NULL, 'Cónico 1000'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCL-1200', 'CONICO', 4, NULL, 'Cónico 1200'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCL-1700', 'CONICO', 5, NULL, 'Cónico 1700'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCL-2500', 'CONICO', 6, NULL, 'Cónico 2500'),
    (nextval('adempiere.seq_dd_productnesting'), 0, 0, 'Y', now(), 100, now(), 100, 'TCL-5200', 'CONICO', 7, NULL, 'Cónico 5200');

-- NOTE: this assumes a sequence adempiere.seq_dd_productnesting exists (standard iDempiere
-- naming for a table's ID sequence). Create it as part of applying create_dd_productnesting.sql
-- through the Application Dictionary, which provisions this automatically — do not create it
-- by hand here to avoid it drifting from whatever the dictionary tooling expects.

-- Not seeded (no NestingFamily defined yet, per ANIDADO_TANQUES_SAP.md §08):
--   TA-3300 / TA-5500 / TA-7700 / TA-11500 (Australiano)
--   TBU-2200 / TBU-3200 / TBD-2200 / TBD-3200 (Botella)
-- Orders containing only these fall through to the original flat calculation, unchanged.

SELECT classification, nestingfamily, seqno, nestedvolume FROM adempiere.dd_productnesting ORDER BY nestingfamily, seqno;
-- verify before COMMIT: 8 CILINDRICO rows (6 sizes, 2 of them doble-capa sharing a SeqNo),
-- 7 CONICO rows, nestedvolume NULL on all of them.

COMMIT;
